import { useState } from "react";
import { AiFillEyeInvisible, AiFillEye } from "react-icons/ai";
import { Link } from "react-router-dom";
import OAuth from "../components/OAuth";
import { createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import { db, auth } from "../firebase";
import { doc, serverTimestamp, setDoc } from "firebase/firestore";
import SignInImage from "../pages/SignInImage";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
export default function SignUp() {
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
  });
  const { name, email, password } = formData;

  function onChange(e) {
    setFormData((prevState) => ({
      ...prevState,
      [e.target.id]: e.target.value,
    }));
  }
  // This method will be used to submit the form data
  // And user Firebase service to create a new user

  const navigate = useNavigate();

  const onSubmit = async (e) => {
    e.preventDefault();
    //const auth = getAuth();

    //Validate form data
    //const emailRegex =  new RegExp(/^[A-Za-z0-9_!#$%&'*+\/=?`{|}~^.-]+@[A-Za-z0-9.-]+$/, "gm");
    if (
      (email === null || email.trim() === "") &&
      (password === null || password.trim() === "")
    ) {
      toast.error("Email and Password cannot be empty!", {
        theme: "light",
      });

      return;
    }
    // test if email is null or empty
    if (email === null || email.trim() === "") {
      toast.error("Email cannot be empty!", {
        theme: "light",
      });
      return;
    }
    // If email is not valid, don't send to Firebase
    // Found the Email type Form data can be validated by the HTML?
    // const isValidEmail = emailRegex.test(email);
    // if (!isValidEmail) {
    //   toast.error("Invalid Email!", {
    //     theme: "light",
    //   });
    //   return;   
    // }

    if (password === null || password.trim() === "") {
      toast.error("Password cannot be empty!", {
        theme: "light",
      });
      return;
    }

    try {
      var userCredential = await createUserWithEmailAndPassword(
        auth,
        email,
        password
      );

      await updateProfile(auth.currentUser, {
        displayName: name,
      });

      const user = userCredential.user;
      const formDataCopy = { ...formData };
      delete formDataCopy.password;
      formDataCopy.timestamp = serverTimestamp();
      // Write to "users" document
      // setDoc(DocumentReference, Data)
      await setDoc(doc(db, "users", user.uid), formDataCopy);
      console.log(user);

      toast.success("Sign up was successful !");
      navigate("/");
    } catch (error) {
      console.log(error.message);
      toast.error(error.message, {
        theme: "light",
      });
    }
  };

  // const onSubmit = (e) => {
  //   e.preventDefault();   // prevent page refresh
  //   //TODO: time to do the authentication check
  //   console.log(formData);
  // }

  return (
    <section>
      <h1 className="text-3xl text-center mt-6 font-bold">Sign Up</h1>
      <div className="flex justify-center flex-wrap items-center px-6 py-12 max-w-6xl mx-auto">
        <SignInImage />
        <div className="w-full md:w-[67%] lg:w-[40%] lg:ml-20">
          <form onSubmit={onSubmit}>  {/*onSubmit is only for the Form, not for the Button, Button has onClick */}
            <input
              type="text"
              id="name"
              value={name}
              onChange={onChange}
              placeholder="Full name"
              className="mb-6 w-full px-4 py-2 text-xl text-gray-700 bg-white border-gray-300 rounded transition ease-in-out"
            />
            <input
              type="email"
              id="email"
              value={email}
              onChange={onChange}
              placeholder="Email address"
              className="mb-6 w-full px-4 py-2 text-xl text-gray-700 bg-white border-gray-300 rounded transition ease-in-out"
            />
            <div className="relative mb-6">
              <input
                type={showPassword ? "text" : "password"}
                id="password"
                value={password}
                onChange={onChange}
                placeholder="Password"
                className="w-full px-4 py-2 text-xl text-gray-700 bg-white border-gray-300 rounded transition ease-in-out"
              />
              {showPassword ? (
                <AiFillEyeInvisible
                  className="absolute right-3 top-3 text-xl cursor-pointer"
                  onClick={() => setShowPassword((prevState) => !prevState)}
                />
              ) : (
                <AiFillEye
                  className="absolute right-3 top-3 text-xl cursor-pointer"
                  onClick={() => setShowPassword((prevState) => !prevState)}
                />
              )}
            </div>
            <div className="flex justify-between whitespace-nowrap text-sm sm:text-lg">
              <p className="mb-6">
                Have a account?
                <Link
                  to="/sign-in"
                  className="text-red-600 hover:text-red-700 transition duration-200 ease-in-out ml-1"
                >
                  Sign in
                </Link>
              </p>
              <p>
                <Link
                  to="/forgot-password"
                  className="text-blue-600 hover:text-blue-800 transition duration-200 ease-in-out"
                >
                  Forgot password?
                </Link>
              </p>
            </div>
            <button
              className="w-full bg-blue-600 text-white px-7 py-3 text-sm font-medium uppercase rounded shadow-md hover:bg-blue-700 transition duration-150 ease-in-out hover:shadow-lg active:bg-blue-800"
              type="submit"
            >
              Sign up
            </button>
            <div className="flex items-center  my-4 before:border-t before:flex-1 before:border-gray-300 after:border-t after:flex-1 after:border-gray-300">
              <p className="text-center font-semibold mx-4">OR</p>
            </div>
            <OAuth />
          </form>
        </div>
      </div>
    </section>
  );
}
